async function createPage(spaceId: string, parentId: string, title: string) {
  const v3Id = "saveTransactions"; // Example ID, replace with the actual ID
  const args = {
    spaceId: spaceId,
    transactions: [
      {
        id: "transaction-id",
        spaceId: spaceId,
        operations: [
          {
            pointer: { id: parentId, table: "block", spaceId: spaceId },
            path: [],
            args: {
              id: "new-page-id",
              type: "page",
              properties: {
